4	
5	func TestLoadDefaults(t *testing.T) {
6		t.Setenv("SVC_ADDR", "")
7		t.Setenv("SVC_DB", "")
8		t.Setenv("SVC_LOG_LEVEL", "")
9		c, err := Load()
10		if err != nil {
11			t.Fatal(err)
12		}
