package config

import (
	"testing"
	"time"
)

func TestLoadDefaults(t *testing.T) {
	t.Setenv("SVC_ADDR", "")
	t.Setenv("SVC_DB", "")
	t.Setenv("SVC_LOG_LEVEL", "")
	t.Setenv("SVC_TIMEOUT", "")
	c, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if c != Defaults {
		t.Fatalf("got %+v want %+v", c, Defaults)
	}
	if c.Timeout != 5*time.Second {
		t.Fatalf("default timeout = %s, want 5s", c.Timeout)
	}
}

func TestLoadOverridesAndValidates(t *testing.T) {
	t.Setenv("SVC_ADDR", "127.0.0.1:9090")
	t.Setenv("SVC_LOG_LEVEL", "DEBUG")
	t.Setenv("SVC_TIMEOUT", "")
	c, err := Load()
	if err != nil || c.Addr != "127.0.0.1:9090" || c.LogLevel != "debug" {
		t.Fatalf("c=%+v err=%v", c, err)
	}
	t.Setenv("SVC_LOG_LEVEL", "loud")
	if _, err := Load(); err == nil {
		t.Fatal("bad log level accepted")
	}
	t.Setenv("SVC_LOG_LEVEL", "info")
	t.Setenv("SVC_ADDR", "nope")
	if _, err := Load(); err == nil {
		t.Fatal("bad addr accepted")
	}
}

func TestLoadTimeoutOverride(t *testing.T) {
	t.Setenv("SVC_ADDR", "")
	t.Setenv("SVC_DB", "")
	t.Setenv("SVC_LOG_LEVEL", "")
	t.Setenv("SVC_TIMEOUT", "2s")
	c, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if c.Timeout != 2*time.Second {
		t.Fatalf("timeout = %s, want 2s", c.Timeout)
	}
}

func TestLoadInvalidTimeout(t *testing.T) {
	t.Setenv("SVC_ADDR", "")
	t.Setenv("SVC_DB", "")
	t.Setenv("SVC_LOG_LEVEL", "")
	t.Setenv("SVC_TIMEOUT", "not-a-duration")
	if _, err := Load(); err == nil {
		t.Fatal("invalid SVC_TIMEOUT accepted")
	}
}

