16	func newTestServer(t *testing.T) *httptest.Server {
17		t.Helper()
18		s := New(config.Defaults, store.NewMemStore(), log.New(io.Discard, "", 0))
19		ts := httptest.NewServer(s.Handler())
20		t.Cleanup(ts.Close)
21		return ts
22	}
23	
24	func TestCreateGetListDelete(t *testing.T) {
25		ts := newTestServer(t)
26		resp, err := http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"p1","name":"pen","tags":["office"]}`))
27		if err != nil || resp.StatusCode != http.StatusCreated {
28			t.Fatalf("create: %v %v", err, resp.Status)
29		}
30		resp, _ = http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"p1","name":"pen"}`))
31		if resp.StatusCode != http.StatusConflict {
32			t.Fatalf("duplicate: %s", resp.Status)
33		}
34		resp, _ = http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"","name":"x"}`))
35		if resp.StatusCode != http.StatusBadRequest {
36			t.Fatalf("empty id: %s", resp.Status)
37		}
38		resp, _ = http.Get(ts.URL + "/items/p1")
39		var it store.Item
40		if err := json.NewDecoder(resp.Body).Decode(&it); err != nil || it.Name != "pen" {
41			t.Fatalf("get: %+v %v", it, err)
42		}
43		resp, _ = http.Get(ts.URL + "/items?tag=office")
44		var list []store.Item
45		if err := json.NewDecoder(resp.Body).Decode(&list); err != nil || len(list) != 1 {
46			t.Fatalf("list by tag: %+v %v", list, err)
47		}
48		req, _ := http.NewRequest(http.MethodDelete, ts.URL+"/items/p1", nil)
49		resp, _ = http.DefaultClient.Do(req)
50		if resp.StatusCode != http.StatusNoContent {
51			t.Fatalf("delete: %s", resp.Status)
52		}
53		resp, _ = http.Get(ts.URL + "/items/p1")
54		if resp.StatusCode != http.StatusNotFound {
55			t.Fatalf("after delete: %s", resp.Status)
56		}
57	}
