59	func TestHTTPServerUsesConfiguredAddr(t *testing.T) {
60		cfg := config.Defaults
61		cfg.Addr = "127.0.0.1:0"
62		hs := New(cfg, store.NewMemStore(), log.New(io.Discard, "", 0)).HTTPServer()
63		if hs.Addr != "127.0.0.1:0" || hs.ReadTimeout == 0 || hs.WriteTimeout == 0 {
64			t.Fatalf("server = %+v", hs)
65		}
66	}

