def test_currency_reads_column(self):
    csv_text = (
        "date,category,amount,currency\n"
        "2024-03-01,food,5.00,EUR\n"
        "2024-03-02,travel,10.00,gbp\n"
        "2024-03-03,food,3.00,\n"
    )
    txs = load_transactions(write(csv_text))
    self.assertEqual(txs[0].currency, "EUR")
    self.assertEqual(txs[1].currency, "GBP")
    self.assertEqual(txs[2].currency, "USD")

